<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class AttendanceEvent extends Model {protected $fillable=['company_id','uuid','attendable_type','attendable_id','title','description','event_type','starts_at','ends_at','attendance_opens_at','attendance_closes_at','status','access_mode','verification_method','requires_signature','allows_external_attendees','public_access_enabled','access_token_hash','access_token_expires_at','token_rotated_at','created_by','updated_by'];protected $casts=['starts_at'=>'datetime','ends_at'=>'datetime','attendance_opens_at'=>'datetime','attendance_closes_at'=>'datetime','access_token_expires_at'=>'datetime','token_rotated_at'=>'datetime','requires_signature'=>'boolean','allows_external_attendees'=>'boolean','public_access_enabled'=>'boolean'];public function getRouteKeyName(){return'uuid';}public function attendable(){return$this->morphTo();}public function company(){return$this->belongsTo(PerfilEmpresa::class,'company_id');}public function participants(){return$this->hasMany(AttendanceParticipant::class);}public function records(){return$this->hasMany(AttendanceRecord::class);}public function audits(){return$this->hasMany(AttendanceAudit::class);}public function evidences(){return$this->hasMany(AttendanceEvidence::class);}public function isOpen():bool{return$this->status==='open'&&$this->public_access_enabled&&now()->gte($this->attendance_opens_at)&&now()->lt($this->attendance_closes_at);}public function scopeOpenNow($query){return$query->where('status','open')->where('public_access_enabled',true)->where('attendance_opens_at','<=',now())->where('attendance_closes_at','>',now());}}
